00042 static DWORD GetProcessByName(PCSTR name)
00043 {
00044     WCHAR wide_name[MAX_PATH] = {};
00045     mbstowcs_s(NULL, wide_name, name, MAX_PATH);
00046 
00047     const scoped_handle snapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
00048 
00049     // Walk through all processes and search for the name
00050     PROCESSENTRY32W process = { sizeof(process) };
00051     for (BOOL next = Process32FirstW(snapshot, &process); next; next = Process32NextW(snapshot, &process))
00052     {
00053         if (wcscmp(process.szExeFile, wide_name) == 0)
00054         {
00055             return process.th32ProcessID;
00056         }
00057     }
00058 
00059     return 0;
00060 }
