00062 DWORD CALLBACK remote_main(BYTE *image_base)
00063 {
00064     #pragma region Initialize module image
00065     const auto headers = reinterpret_cast<const IMAGE_NT_HEADERS *>(image_base + reinterpret_cast<const IMAGE_DOS_HEADER *>(image_base)->e_lfanew);
00066 
00067     // Apply base relocations
00068     const auto relocation_delta = image_base - reinterpret_cast<const BYTE *>(headers->OptionalHeader.ImageBase);
00069 
00070     if (relocation_delta != 0) // No need to relocate anything if the delta is zero
00071     {
00072         auto relocation = reinterpret_cast<const IMAGE_BASE_RELOCATION *>(image_base + headers->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_BASERELOC].VirtualAddress);
00073 
00074         while (relocation->VirtualAddress != 0)
00075         {
00076             const auto field_count = (relocation->SizeOfBlock - sizeof(IMAGE_BASE_RELOCATION)) / sizeof(WORD);
00077 
00078             for (size_t k = 0; k < field_count; k++)
00079             {
00080                 const WORD field = reinterpret_cast<const WORD *>(relocation + 1)[k];
00081 
00082                 switch (field >> 12)
00083                 {
00084                 case IMAGE_REL_BASED_ABSOLUTE:
00085                     break; // This one does not do anything and exists only for table alignment, so ignore it
00086                 case IMAGE_REL_BASED_HIGHLOW:
00087                     *reinterpret_cast<UINT32 *>(image_base + relocation->VirtualAddress + (field & 0xFFF)) += static_cast<INT32>(relocation_delta);
00088                     break;
00089                 case IMAGE_REL_BASED_DIR64:
00090                     *reinterpret_cast<UINT64 *>(image_base + relocation->VirtualAddress + (field & 0xFFF)) += static_cast<INT64>(relocation_delta);
00091                     break;
00092                 default:
00093                     return ERROR_IMAGE_AT_DIFFERENT_BASE; // Exit when encountering an unknown relocation type
00094                 }
00095             }
00096 
00097             relocation = reinterpret_cast<const IMAGE_BASE_RELOCATION *>(reinterpret_cast<const BYTE *>(relocation) + relocation->SizeOfBlock);
00098         }
00099     }
00100 
00101     // Update import address table (IAT)
00102     const auto import_directory_entries = reinterpret_cast<const IMAGE_IMPORT_DESCRIPTOR *>(image_base + headers->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT].VirtualAddress);
00103 
00104     for (size_t i = 0; import_directory_entries[i].FirstThunk != 0; i++)
00105     {
00106         const auto name = reinterpret_cast<const char *>(image_base + import_directory_entries[i].Name);
00107         const auto import_name_table = reinterpret_cast<const IMAGE_THUNK_DATA *>(image_base + import_directory_entries[i].Characteristics);
00108         const auto import_address_table = reinterpret_cast<IMAGE_THUNK_DATA *>(image_base + import_directory_entries[i].FirstThunk);
00109 
00110         // It is safe to call 'LoadLibrary' here because the IAT entry for it was copied from the parent process and KERNEL32.dll is always loaded at the same address
00111         const HMODULE module = LoadLibraryA(name);
00112 
00113         if (module == nullptr)
00114             continue;
00115 
00116         for (size_t k = 0; import_name_table[k].u1.AddressOfData != 0; k++)
00117         {
00118             if (IMAGE_SNAP_BY_ORDINAL(import_name_table[k].u1.Ordinal))
00119             {
00120                 // Import by ordinal
00121                 const auto import = IMAGE_ORDINAL(import_name_table[k].u1.Ordinal);
00122 
00123                 import_address_table[k].u1.AddressOfData = reinterpret_cast<DWORD_PTR>(GetProcAddress(module, reinterpret_cast<LPCSTR>(import)));
00124             }
00125             else
00126             {
00127                 // Import by function name
00128                 const auto import = reinterpret_cast<const IMAGE_IMPORT_BY_NAME *>(image_base + import_name_table[k].u1.AddressOfData);
00129 
00130                 import_address_table[k].u1.AddressOfData = reinterpret_cast<DWORD_PTR>(GetProcAddress(module, import->Name));
00131             }
00132         }
00133     }
00134 
00135     // Call global C/C++ constructors
00136     _initterm(__xi_a, __xi_z);
00137     _initterm(__xc_a, __xc_z);
00138     #pragma endregion
00139 
00140     scoped_handle blink_handle = CreateFileA(blink_pipe_name, GENERIC_READ | GENERIC_WRITE, 0, NULL, OPEN_ALWAYS, FILE_FLAG_WRITE_THROUGH, NULL);
00141 
00142     // Run main loop
00143     blink::application().run(blink_handle, blink_environment, blink_working_directory, compile_source);
00144 
00145     CloseHandle(console);
00146 
00147     return 0;
00148 }
