00150 int main(int argc, char *argv[])
00151 {
00152     DWORD pid = 0;
00153 
00154     if (argc > 1)
00155     {
00156         int i = 1;
00157 
00158         for (; i < argc; i++)
00159         {
00160             if (std::strcmp(argv[i], "-h") == 0 || std::strcmp(argv[i], "--help") == 0)
00161             {
00162                 std::cout << "usage: " << argv[0] << " [options] <...>" << std::endl;
00163                 std::cout << "  <...>              PID or name of running process, or command-line of target application to launch" << std::endl;
00164                 std::cout << "  -h/--help          Show this help message" << std::endl;
00165                 std::cout << "  --no-compile       Watch for changes to object files and link them directly, rather than source files and compiling them first" << std::endl;
00166                 return 0;
00167             }
00168             if (std::strcmp(argv[i], "--no-compile") == 0)
00169             {
00170                 compile_source = false;
00171                 continue;
00172             }
00173 
00174             // Argument is not an option, so assume this starts the remaining command-line
00175             break;
00176         }
00177 
00178         // Attach to running process by PID
00179         pid = std::strtoul(argv[i], nullptr, 0);
00180 
00181         if (pid == 0)
00182         {
00183             // Try to look up PID of running process by name
00184             pid = GetProcessByName(argv[i]);
00185         }
00186 
00187         if (pid == 0)
00188         {
00189             // Launch target application with remaining command-line and determine PID
00190             STARTUPINFOA startup_info = { sizeof(startup_info) };
00191             PROCESS_INFORMATION process_info = {};
00192 
00193             std::string command_line;
00194             for (; i < argc; ++i, command_line += ' ')
00195                 command_line += argv[i];
00196 
00197             if (!CreateProcessA(nullptr, command_line.data(), nullptr, nullptr, FALSE, CREATE_NEW_CONSOLE, nullptr, nullptr, &startup_info, &process_info))
00198             {
00199                 std::cout << "Failed to start target application process!" << std::endl;
00200                 return GetLastError();
00201             }
00202 
00203             pid = process_info.dwProcessId;
00204 
00205             CloseHandle(process_info.hThread);
00206             CloseHandle(process_info.hProcess);
00207         }
00208     }
00209 
00210     if (pid == 0)
00211     {
00212         std::cout << "Enter PID of target application: ";
00213         std::cin >> pid;
00214     }
00215 
00216     // Open target application process
00217     const HANDLE local_process = GetCurrentProcess();
00218     const scoped_handle remote_process = OpenProcess(PROCESS_CREATE_THREAD | PROCESS_VM_OPERATION | PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_DUP_HANDLE | PROCESS_QUERY_INFORMATION, FALSE, pid);
00219 
00220     if (remote_process == nullptr)
00221     {
00222         std::cout << "Failed to open target application process!" << std::endl;
00223         return GetLastError();
00224     }
00225 
00226     BOOL local_is_wow64 = FALSE, remote_is_wow64 = FALSE;
00227     IsWow64Process(local_process, &local_is_wow64);
00228     IsWow64Process(remote_process, &remote_is_wow64);
00229 
00230     if (local_is_wow64 != remote_is_wow64)
00231     {
00232         std::cout << "Machine architecture mismatch between target application and this application!" << std::endl;
00233         return ERROR_IMAGE_MACHINE_TYPE_MISMATCH;
00234     }
00235 
00236     std::cout << "Launching in target application ..." << std::endl;
00237 
00238     // Create a pipe for communication between this process and the target application
00239     scoped_handle local_pipe;
00240     if (!CreatePipe(&local_pipe, &console, nullptr, 512) || !DuplicateHandle(local_process, console, remote_process, &console, 0, FALSE, DUPLICATE_CLOSE_SOURCE | DUPLICATE_SAME_ACCESS))
00241     {
00242         std::cout << "Failed to create new communication pipe!" << std::endl;
00243         return GetLastError();
00244     }
00245 
00246     MODULEINFO module_info;
00247     if (!GetModuleInformation(GetCurrentProcess(), GetModuleHandle(nullptr), &module_info, sizeof(module_info)))
00248         return GetLastError();
00249 
00250 #ifdef _DEBUG // Use 'LoadLibrary' to create image in target application so that debug information is loaded
00251     WCHAR load_path[MAX_PATH];
00252     WCHAR load_path_canonicalized[MAX_PATH];
00253     GetModuleFileNameW(nullptr, load_path, MAX_PATH);
00254     PathCchCanonicalize(load_path_canonicalized, MAX_PATH, load_path);
00255 
00256     const auto load_param = VirtualAllocEx(remote_process, nullptr, MAX_PATH, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
00257 
00258     // Write 'LoadLibrary' call argument to target application
00259     if (load_param == nullptr || !WriteProcessMemory(remote_process, load_param, load_path, MAX_PATH, nullptr))
00260     {
00261         std::cout << "Failed to allocate and write 'LoadLibrary' argument in target application!" << std::endl;
00262         return GetLastError();
00263     }
00264 
00265     // Execute 'LoadLibrary' in target application
00266     const scoped_handle load_thread = CreateRemoteThread(remote_process, nullptr, 0, reinterpret_cast<LPTHREAD_START_ROUTINE>(&LoadLibraryW), load_param, 0, nullptr);
00267 
00268     if (load_thread == nullptr)
00269     {
00270         std::cout << "Failed to execute 'LoadLibrary' in target application!" << std::endl;
00271         return GetLastError();
00272     }
00273 
00274     // Wait for loading to finish and clean up parameter memory afterwards
00275     WaitForSingleObject(load_thread, INFINITE);
00276     VirtualFreeEx(remote_process, load_param, 0, MEM_RELEASE);
00277 
00278     // Find address of the now loaded module in the target application process
00279     DWORD modules_size = 0;
00280     EnumProcessModulesEx(remote_process, nullptr, 0, &modules_size, LIST_MODULES_ALL);
00281     std::vector<HMODULE> modules(modules_size / sizeof(HMODULE));
00282     EnumProcessModulesEx(remote_process, modules.data(), modules_size, &modules_size, LIST_MODULES_ALL);
00283 
00284     BYTE *remote_baseaddress = nullptr;
00285 
00286     for (HMODULE module : modules)
00287     {
00288         WCHAR module_path[MAX_PATH];
00289         WCHAR module_path_canonicalized[MAX_PATH];
00290         GetModuleFileNameExW(remote_process, module, module_path, MAX_PATH);
00291         PathCchCanonicalize(module_path_canonicalized, MAX_PATH, module_path);
00292 
00293         if (lstrcmpW(module_path_canonicalized, load_path_canonicalized) == 0)
00294         {
00295             remote_baseaddress = reinterpret_cast<BYTE *>(module);
00296             break;
00297         }
00298     }
00299 
00300     // Make the entire image writable so the copy operation below can succeed
00301     if (remote_baseaddress != nullptr)
00302     {
00303         VirtualProtectEx(remote_process, remote_baseaddress, module_info.SizeOfImage, PAGE_EXECUTE_READWRITE, &modules_size);
00304     }
00305 #else
00306     const auto remote_baseaddress = static_cast<BYTE *>(VirtualAllocEx(remote_process, nullptr, module_info.SizeOfImage, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE));
00307 #endif
00308 
00309     _snprintf_s(blink_pipe_name, sizeof(blink_pipe_name), "\\\\.\\pipe\\blink-%d", GetCurrentProcessId());
00310 #define NAMED_PIPE_SIZE 1024
00311     // use duplex named pipe, so remote thread can quit and free up memory, when blink.exe quits
00312     scoped_handle blink_pipe_handle = CreateNamedPipeA(
00313         reinterpret_cast<LPCSTR>(blink_pipe_name),
00314         PIPE_ACCESS_DUPLEX
00315         | FILE_FLAG_WRITE_THROUGH,
00316         PIPE_TYPE_BYTE | PIPE_WAIT,
00317         1, NAMED_PIPE_SIZE, NAMED_PIPE_SIZE,
00318         10000, NULL);
00319     if (!blink_pipe_handle)
00320     {
00321         std::cout << "Failed to create blink pipe!" << std::endl;
00322         return GetLastError();
00323     }
00324 
00325     // Get blink.exe's environment, so we can use it for compiles in the remote thread.
00326     const LPWCH environment = GetEnvironmentStringsW();
00327     LPWCH environment_end = environment;
00328     for (; *environment_end != '\0'; environment_end += wcslen(environment_end) + 1)
00329     {
00330         // continue until we find the double null end
00331     }
00332     environment_end += 1; // get position after the double null end
00333     const size_t environment_length = environment_end - environment;
00334     if (environment_length > MAX_ENVIRONMENT_LENGTH)
00335     {
00336         std::cout << "Environment string exceeded max length!" << std::endl;
00337         return ERROR_NOT_ENOUGH_MEMORY;
00338     }
00339     memcpy(blink_environment, environment, environment_length * sizeof(wchar_t));
00340     FreeEnvironmentStringsW(environment);
00341 
00342     // Get blink.exe's working directory, so we can use it for compiles in the remote thread.
00343     wcscpy_s(blink_working_directory, std::filesystem::current_path().c_str());
00344 
00345     // Copy current module image to target application (including the IAT and value of the global variables)
00346     if (remote_baseaddress == nullptr || !WriteProcessMemory(remote_process, remote_baseaddress, module_info.lpBaseOfDll, module_info.SizeOfImage, nullptr))
00347     {
00348         std::cout << "Failed to allocate and write image in target application!" << std::endl;
00349         return GetLastError();
00350     }
00351 
00352     // Launch module main entry point in target application
00353     const auto remote_entrypoint = remote_baseaddress + (reinterpret_cast<BYTE *>(&remote_main) - static_cast<BYTE *>(module_info.lpBaseOfDll));
00354     std::cout << "  Entry point was written to address " << static_cast<const void *>(remote_baseaddress) << std::endl;
00355     const scoped_handle remote_thread = CreateRemoteThread(remote_process, nullptr, 0, reinterpret_cast<LPTHREAD_START_ROUTINE>(remote_entrypoint), remote_baseaddress, 0, nullptr);
00356 
00357     if (remote_thread == nullptr)
00358     {
00359         std::cout << "Failed to launch remote thread in target application!" << std::endl;
00360         return GetLastError();
00361     }
00362 
00363     // Run main loop and pass on incoming messages to console
00364     while (WaitForSingleObject(remote_thread, 0))
00365     {
00366         char message[512] = "";
00367         DWORD size = ARRAYSIZE(message);
00368 
00369         if (!ReadFile(local_pipe, message, size, &size, nullptr) || size == 0)
00370             continue;
00371 
00372         WriteFile(GetStdHandle(STD_OUTPUT_HANDLE), message, size, &size, nullptr);
00373     }
00374 
00375     DWORD exitcode = 0, remote_exitcode = 0;
00376     GetExitCodeThread(remote_thread, &exitcode);
00377     GetExitCodeProcess(remote_process, &remote_exitcode);
00378 
00379     std::cout << "The target application has exited with code " << remote_exitcode << "." << std::endl;
00380 
00381     return static_cast<int>(exitcode);
00382 }
